begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','43100000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('43100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','calendar-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('External calendar fixture','Pacific/Kiritimati','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Calendar category' from ctx returning id) select * from c;
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Timed","kind":"other","activity_type":"event","estimated_cost_minor":1000,"starts_at":"2026-10-07T23:30:00Z","is_all_day":false}',null)).id;
create temp table allday as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"All day","kind":"other","activity_type":"task","starts_at":"2026-10-07T10:00:00Z","is_all_day":true}',null)).id;
create temp table series as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Weekly","kind":"other","activity_type":"task","starts_at":"2026-10-07T10:00:00Z","recurrence_frequency":"weekly","recurrence_interval":1,"recurrence_start_date":"2026-10-08","recurrence_active":true}',null)).id;
create temp table decision as select public.create_decision((select id from ctx),'Choose',null,null,'[{"title":"A"},{"title":"B"}]') id;
create temp table schedule as with s as(insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select ctx.id,activity.id,'Deposit',1000,'2026-10-08' from ctx,activity returning id) select * from s;
insert into public.payments(project_id,commitment_id,payment_schedule_id,type,status,amount_minor,due_on) select ctx.id,activity.id,schedule.id,'deposit','scheduled',1000,'2026-10-08' from ctx,activity,schedule;
set local role postgres;
update public.decisions set voting_deadline='2026-10-07T23:30:00Z' where id=(select id from decision);
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('43100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Calendar member '||i,case when i=3 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,4) i;
select pg_temp.login(1);

set local role postgres;
update public.commitments set starts_at=now(),ends_at=now()+interval '2 hours' where id in(select id from activity union all select id from allday);
update public.commitments set starts_at=now(),recurrence_start_date=(now() at time zone 'Pacific/Kiritimati')::date where id=(select id from series);
update public.decisions set voting_deadline=now() where id=(select id from decision);
update public.activity_payment_schedules set due_on=(now() at time zone 'Pacific/Kiritimati')::date where id=(select id from schedule);
create function pg_temp.connect_user(i integer) returns uuid language plpgsql as $$
declare u uuid:=('43100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid; h text:=repeat(i::text,64); r jsonb;
begin
 perform public.calendar_backend('state_create',jsonb_build_object('user_id',u,'hash',h,'verifier','test-verifier'));
 perform public.calendar_backend('state_consume',jsonb_build_object('hash',h));
 r:=public.calendar_backend('connect',jsonb_build_object('user_id',u,'hash',h,'subject','fixture-'||i,'email','fixture@example.test','access_token','synthetic-access','refresh_token','synthetic-refresh','expires_at',now()+interval '1 hour'));
 return (r->>'id')::uuid;
end $$;
create temp table connections as select i,pg_temp.connect_user(i) id from generate_series(1,5) i;
grant select on connections to authenticated;
select is((select count(*)::int from app.external_calendar_jobs where connection_id in(select id from connections)),5,'Initial sync queued once per user');
select ok(not exists(select 1 from public.user_calendar_connections where id in(select id from connections) and payments),'Payments opt-in defaults off');
select ok(not exists(select 1 from information_schema.columns where table_schema='public' and table_name='user_calendar_connections' and column_name ~ '(token|secret)'),'Public connection has no tokens or secret references');
select ok(not exists(select 1 from pg_class where relname='calendar_events'),'No duplicated calendar_events table');
select ok((select rolbypassrls=false and rolcanlogin=false from pg_roles where rolname='orchestrio_calendar_reader'),'Projection role cannot bypass RLS or log in');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.user_calendar_connections'::regclass),'Connection ENABLE and FORCE RLS');
select pg_temp.login(1);
select is((select count(*)::int from public.user_calendar_connections),1,'Owner reads own connection only');
select is((select count(*)::int from public.user_calendar_connections where id=(select id from connections where i=2)),0,'Organizer has no connection override');
select throws_ok($$update public.user_calendar_connections set payments=true$$,'42501',null,'Browser cannot directly mutate connections');
select throws_ok($$select public.calendar_backend('bundle')$$,'42501',null,'Browser cannot call trusted backend');
select throws_ok($$select * from app.calendar_credentials$$,'42501',null,'Credentials inaccessible');
select throws_ok($$select * from app.external_calendar_event_links$$,'42501',null,'Mappings inaccessible');
select throws_ok($$select * from app.external_calendar_jobs$$,'42501',null,'Jobs inaccessible');
select throws_ok($$select * from app.external_calendar_receipts$$,'42501',null,'Receipts inaccessible');
select throws_ok($$select * from app.calendar_oauth_states$$,'42501',null,'OAuth state inaccessible');
select throws_ok($$select app.calendar_projection_for_user('43100000-0000-4000-8000-000000000002')$$,'42501',null,'Cannot spoof projection owner');
select lives_ok($$select public.request_calendar_sync()$$,'Owner can request reconciliation');
select lives_ok($$select public.request_calendar_sync()$$,'Repeated request coalesces');
set local role anon;
select throws_ok($$select * from public.user_calendar_connections$$,'42501',null,'Anonymous connection read denied');
select throws_ok($$select public.request_calendar_sync()$$,'42501',null,'Anonymous sync denied');
set local role postgres;
select is((select count(*)::int from app.external_calendar_jobs where connection_id=(select id from connections where i=1)),1,'One pending job despite retries');
create temp table projection as select app.calendar_projection_for_user('43100000-0000-4000-8000-000000000001') entries;
select ok(exists(select 1 from projection,jsonb_array_elements(entries) e where e->>'source_type'='activity'),'Activity eligible');
select ok(exists(select 1 from projection,jsonb_array_elements(entries) e where e->>'source_type'='decision'),'Decision eligible');
select ok(exists(select 1 from projection,jsonb_array_elements(entries) e where e->>'source_type'='payment_schedule'),'Payment projection available to preference filter');
select ok(exists(select 1 from projection,jsonb_array_elements(entries) e where e->>'source_type'='activity_occurrence' and e->>'entry_id' like 'occurrence:%'),'Actual Phase 12 occurrence identity reused');
select ok(not exists(select 1 from projection,jsonb_array_elements(entries) e where e->>'source_id'=(select id::text from series) and e->>'source_type'='activity'),'No recurring parent duplication');
select ok(not exists(select 1 from projection,jsonb_array_elements(entries) e where e ? 'amount_minor' or e ? 'assigned_member' or e ? 'description'),'Minimal projection strips financial/private metadata');
select ok(not exists(select 1 from projection,jsonb_array_elements(entries) e where e->>'source_type' not in ('activity','activity_occurrence','decision','payment_schedule')),'No reimbursements, notifications, health or operational events');
select is(jsonb_array_length(app.calendar_projection_for_user('43100000-0000-4000-8000-000000000002')),(select jsonb_array_length(entries) from projection),'Member sees legitimate sources');
select is(jsonb_array_length(app.calendar_projection_for_user('43100000-0000-4000-8000-000000000003')),(select jsonb_array_length(entries) from projection),'Viewer sees only legitimate sources');
select is(app.calendar_projection_for_user('43100000-0000-4000-8000-000000000005'),'[]'::jsonb,'Outsider projection empty despite trusted backend');
update public.project_members set status='removed' where project_id=(select id from ctx) and user_id='43100000-0000-4000-8000-000000000004';
select is(app.calendar_projection_for_user('43100000-0000-4000-8000-000000000004'),'[]'::jsonb,'Removed membership immediately excludes sources');
-- Keep only the organizer job eligible for deterministic worker tests.
update app.external_calendar_jobs set available_at=now()+interval '1 day' where connection_id<>(select id from connections where i=1);
create temp table job as select public.calendar_backend('claim') value;
create function pg_temp.work(a text,d jsonb default '{}') returns jsonb language sql as $$ select public.calendar_backend(a,(select jsonb_build_object('job_id',value->>'id','lease',value->>'lease') from job)||d) $$;
select ok((select value->>'status'='running' from job),'Claim creates a running lease');
select is(public.calendar_backend('claim'),null::jsonb,'Concurrent claim cannot take leased work');
select throws_ok($$select public.calendar_backend('bundle','{"job_id":"00000000-0000-4000-8000-000000000001","lease":"00000000-0000-4000-8000-000000000001"}')$$,'42501',null,'Forged lease rejected');
select ok(not exists(select 1 from jsonb_array_elements(pg_temp.work('projection')) e where e->>'source_type'='payment_schedule'),'Payments excluded by default');
select pg_temp.login(1);
select public.request_calendar_sync(false,true,true);
set local role postgres;
select ok(not exists(select 1 from jsonb_array_elements(pg_temp.work('projection')) e where e->>'source_type' in ('activity','activity_occurrence')),'Activity preference filters current projection');
select ok(exists(select 1 from jsonb_array_elements(pg_temp.work('projection')) e where e->>'source_type'='decision'),'Decision remains enabled');
select ok(exists(select 1 from jsonb_array_elements(pg_temp.work('projection')) e where e->>'source_type'='payment_schedule'),'Payment opt-in takes effect');
select pg_temp.login(1);
select public.request_calendar_sync(true,true,false);
set local role postgres;
create temp table reserved as select pg_temp.work('reserve',jsonb_build_object('source_key','activity:'||(select id from activity))) value;
select is(pg_temp.work('reserve',jsonb_build_object('source_key','activity:'||(select id from activity))),(select value from reserved),'Repeated reservation retains provider ID');
select is((select count(*)::int from app.external_calendar_event_links where connection_id in(select id from connections)),1,'Mapping uniqueness');
select pg_temp.work('reserve',jsonb_build_object('source_key','occurrence:'||(select id from series)||':2026-10-08'));
select pg_temp.work('reserve',jsonb_build_object('source_key','occurrence:'||(select id from series)||':2026-10-15'));
select is((select count(*)::int from app.external_calendar_event_links where connection_id in(select id from connections)),3,'Occurrence dates distinguish mappings');
-- Worker process crashes must consume the same finite retry budget.
update app.external_calendar_jobs set lease_until=now()-interval '1 second',attempt=4 where id=(select (value->>'id')::uuid from job);
select is(public.calendar_backend('claim'),null::jsonb,'Expired fifth lease is not reclaimed forever');
select is((select status from app.external_calendar_jobs where id=(select (value->>'id')::uuid from job)),'failed','Crash exhaustion is terminal');
select throws_ok($$select pg_temp.work('bundle')$$,'42501',null,'Expired lease cannot resume');
select pg_temp.login(1);
select public.request_calendar_sync();
set local role postgres;
update job set value=public.calendar_backend('claim');
create temp table domain_before as select
 (select count(*)::int from app.external_calendar_jobs where connection_id=(select id from connections where i=1)) jobs,
 (select jsonb_agg(to_jsonb(c)) from public.commitments c where project_id=(select id from ctx)) activities,
 (select jsonb_agg(to_jsonb(d)) from public.decisions d where project_id=(select id from ctx)) decisions,
 (select jsonb_agg(to_jsonb(s)) from public.activity_payment_schedules s where project_id=(select id from ctx)) schedules,
 (select jsonb_agg(to_jsonb(p)) from public.payments p where project_id=(select id from ctx)) payments;
select pg_temp.work('token',jsonb_build_object('access_token','rotated-synthetic','expires_at',now()+interval '2 hours'));
select pg_temp.work('synced',jsonb_build_object('source_key','activity:'||(select id from activity)));
select pg_temp.work('fail','{"code":"transient"}');
select is((select status from app.external_calendar_jobs where id=(select (value->>'id')::uuid from job)),'pending','Provider failure schedules retry');
select is((select attempt from app.external_calendar_jobs where id=(select (value->>'id')::uuid from job)),1,'Retry bounded counter increment');
select ok((select available_at>=now()+interval '60 seconds' from app.external_calendar_jobs where id=(select (value->>'id')::uuid from job)),'Retry has backoff');
select is((select jsonb_agg(to_jsonb(c)) from public.commitments c where project_id=(select id from ctx)),(select activities from domain_before),'Sync never mutates Activity dates');
select is((select jsonb_agg(to_jsonb(d)) from public.decisions d where project_id=(select id from ctx)),(select decisions from domain_before),'Sync never mutates Decision deadlines');
select is((select jsonb_agg(to_jsonb(s)) from public.activity_payment_schedules s where project_id=(select id from ctx)),(select schedules from domain_before),'Sync never mutates financial schedules');
select is((select jsonb_agg(to_jsonb(p)) from public.payments p where project_id=(select id from ctx)),(select payments from domain_before),'Sync never mutates ledger');
select pg_temp.login(1);
select lives_ok($$update public.commitments set starts_at=now()+interval '1 day',ends_at=now()+interval '2 days' where id=(select id from activity)$$,'Activity mutation succeeds during provider outage');
select lives_ok($$update public.commitments set status='cancelled' where id=(select id from allday)$$,'Cancellation independent of provider');
set local role postgres;
select ok(not exists(select 1 from jsonb_array_elements(app.calendar_projection_for_user('43100000-0000-4000-8000-000000000001')) e where e->>'source_id'=(select id::text from allday)),'Cancellation absent from desired set creates reconciliation delete work');
select is((select count(*)::int from app.external_calendar_jobs where connection_id=(select id from connections where i=1)),(select jobs from domain_before),'Domain mutations do not couple to queue');
update app.external_calendar_jobs set available_at=now(),attempt=4 where id=(select (value->>'id')::uuid from job);
update job set value=public.calendar_backend('claim');
select pg_temp.work('fail','{"code":"quota"}');
select is((select status from app.external_calendar_jobs where id=(select (value->>'id')::uuid from job)),'failed','Fifth provider failure stops retries');
select is(public.calendar_backend('claim'),null::jsonb,'Scheduler does not restart exhausted retries');
select pg_temp.login(1);
select public.request_calendar_sync();
set local role postgres;
update job set value=public.calendar_backend('claim');
select pg_temp.work('fail','{"code":"auth"}');
select is((select status from public.user_calendar_connections where id=(select id from connections where i=1)),'reauthorization_required','Invalid grant requires reconnect');
select is(public.calendar_backend('claim'),null::jsonb,'Revoked token never hammered');
-- Explicit container recovery and ambiguous creation policy.
select pg_temp.connect_user(1);
update job set value=public.calendar_backend('claim');
select pg_temp.work('provision_begin');
select pg_temp.work('fail','{"code":"provisioning_uncertain"}');
select throws_ok($$select pg_temp.connect_user(1)$$,'P0001','Disconnect and check Google Calendar before reconnecting','Ambiguous container creation cannot be blindly retried');
select public.calendar_backend('disconnect','{"user_id":"43100000-0000-4000-8000-000000000001"}') is not null;
select pg_temp.connect_user(1);
update job set value=public.calendar_backend('claim');
select pg_temp.work('provision_begin');
select pg_temp.work('provision_finish','{"calendar_id":"synthetic-calendar"}');
select pg_temp.work('reserve',jsonb_build_object('source_key','activity:'||(select id from activity)));
select pg_temp.work('fail','{"code":"calendar_missing"}');
select is((select status from public.user_calendar_connections where id=(select id from connections where i=1)),'degraded','Deleted calendar requires explicit reconnect');
select pg_temp.connect_user(1);
update job set value=public.calendar_backend('claim');
select ok((pg_temp.work('bundle')->>'calendar_id') is null,'Explicit reconnect resets deleted container');
select is(jsonb_array_length(pg_temp.work('links')),0,'Deleted container rebuild starts with no stale mappings');
-- OAuth replay, expiry, and disconnect during code exchange.
select public.calendar_backend('state_create','{"user_id":"43100000-0000-4000-8000-000000000001","hash":"expiry","verifier":"private-verifier"}');
update app.calendar_oauth_states set expires_at=now()-interval '1 minute' where state_hash='expiry';
select is(public.calendar_backend('state_consume','{"hash":"expiry"}'),null::jsonb,'Expired state rejected and erased');
select throws_ok($$select public.calendar_backend('state_consume','{"hash":"invalid"}')$$,'42501',null,'Invalid state rejected');
select public.calendar_backend('state_create','{"user_id":"43100000-0000-4000-8000-000000000001","hash":"race","verifier":"private-verifier"}');
select public.calendar_backend('state_consume','{"hash":"race"}');
select throws_ok($$select public.calendar_backend('state_consume','{"hash":"race"}')$$,'42501',null,'Callback single-use');
create temp table secret_ids as select access_secret id from app.calendar_credentials where connection_id=(select id from connections where i=1) union all select refresh_secret from app.calendar_credentials where connection_id=(select id from connections where i=1);
select public.calendar_backend('disconnect','{"user_id":"43100000-0000-4000-8000-000000000001"}') is not null;
select throws_ok($$select public.calendar_backend('connect','{"user_id":"43100000-0000-4000-8000-000000000001","hash":"race"}')$$,'42501',null,'Disconnect invalidates in-flight OAuth completion');
select is((select status from public.user_calendar_connections where id=(select id from connections where i=1)),'disconnected','Local disconnect unconditional');
select is((select count(*)::int from vault.secrets where id in(select id from secret_ids)),0,'Disconnect erases both Vault secrets');
select is((select count(*)::int from app.external_calendar_event_links where connection_id=(select id from connections where i=1)),0,'Disconnect removes mappings');
select throws_ok($$select pg_temp.work('bundle')$$,'42501',null,'Old worker lease cannot act after disconnect');
select pg_temp.login(1);
select throws_ok($$select public.request_calendar_sync()$$,'42501',null,'Disconnected user cannot schedule work');
set local role postgres;
select ok(not exists(select 1 from public.audit_log where after::text like '%synthetic-refresh%'),'Tokens absent from audit');
select ok(has_function_privilege('service_role','public.calendar_backend(text,jsonb)','EXECUTE'),'Trusted service can execute backend');
select ok(not exists(select 1 from vault.decrypted_secrets where decrypted_secret='private-verifier'),'Expired and consumed PKCE secrets erased');
select is(current_setting('request.jwt.claims',true)::jsonb->>'sub','43100000-0000-4000-8000-000000000001','Projection restores caller claims');
update public.projects set status='archived' where id=(select id from ctx);
select ok(jsonb_array_length(app.calendar_projection_for_user('43100000-0000-4000-8000-000000000002'))>0,'Readable archived project follows bounded projection');
update public.projects set status='active' where id=(select id from ctx);
select public.soft_delete_project((select id from ctx));
select is(app.calendar_projection_for_user('43100000-0000-4000-8000-000000000002'),'[]'::jsonb,'Deleted project is removed from desired external set');
-- No credential is entrusted to the platform-owned pg_net transport queue.
select ok(not exists(select 1 from vault.secrets where name='orchestrio.calendar_worker_key'),'No permanent worker credential remains');
select pg_temp.login(1);
select throws_ok($$select public.calendar_worker_wakeup()$$,'42501',null,'Browser cannot authorize a worker');
select throws_ok($$select * from app.calendar_worker_dispatch$$,'42501',null,'Dispatch window is private');
set local role postgres;
delete from app.calendar_worker_dispatch;
select is(public.calendar_worker_wakeup(),false,'Unscheduled HTTP wake-up cannot authorize work');
do $$ declare secret_id uuid; begin
 select id into secret_id from vault.secrets where name='orchestrio.calendar_worker_url';
 if secret_id is null then perform vault.create_secret('https://example.test/worker','orchestrio.calendar_worker_url');
 else perform vault.update_secret(secret_id,'https://example.test/worker'); end if;
end $$;
select app.request_external_calendar_worker();
select ok(exists(select 1 from net.http_request_queue where url='https://example.test/worker' and headers='{"Content-Type":"application/json"}'::jsonb),'Transport contains only a non-secret wake-up');
select is(public.calendar_worker_wakeup(),true,'Cron-issued window authorizes exactly one run');
select is(public.calendar_worker_wakeup(),false,'Concurrent/replayed wake-up rejected');
select app.request_external_calendar_worker();
select is(public.calendar_worker_wakeup(),false,'Two-minute dispatch cooldown prevents repeated runs');
update app.calendar_worker_dispatch set ready_until=now()-interval '1 second',last_started_at=null;
select is(public.calendar_worker_wakeup(),false,'Expired dispatch rejected');
select * from finish();
rollback;
